Here is the commit message:
IB/mlx5: Fix steering resource leak

Fix multicast flow rule leak on adding unicast rule failure.

Fixes: 038d2ef87572 ('IB/mlx5: Add flow steering support')
Signed-off-by: Maor Gottlieb <maorg@mellanox.com>
Signed-off-by: Leon Romanovsky <leon@kernel.org>
Signed-off-by: Doug Ledford <dledford@redhat.com>

Here is the root cause:
The bug is caused by a failure to properly manage resources when adding a unicast flow rule. If the creation of the unicast rule fails, the existing multicast flow rule is not deleted, leading to a resource leak. This occurs because the error handling did not include a step to clean up the multicast rule, resulting in unfreed memory or resources that could accumulate over time.

Here is the patch:

 static struct mlx5_ib_flow_handler *create_leftovers_rule(struct mlx5_ib_dev *dev,
 							  struct mlx5_ib_flow_prio *ft_prio,
 							  struct ib_flow_attr *flow_attr,
 							  struct mlx5_flow_destination *dst)
 {
 	struct mlx5_ib_flow_handler *handler_ucast = NULL;
 	struct mlx5_ib_flow_handler *handler = NULL;

 	static struct {
 		struct ib_flow_attr	flow_attr;
 		struct ib_flow_spec_eth eth_flow;
 	} leftovers_specs[] = {
 		[LEFTOVERS_MC] = {
 			.flow_attr = {
 				.num_of_specs = 1,
 				.size = sizeof(leftovers_specs[0])
 			},
 			.eth_flow = {
 				.type = IB_FLOW_SPEC_ETH,
 				.size = sizeof(struct ib_flow_spec_eth),
 				.mask = {.dst_mac = {0x1} },
 				.val =  {.dst_mac = {0x1} }
 			}
 		},
 		[LEFTOVERS_UC] = {
 			.flow_attr = {
 				.num_of_specs = 1,
 				.size = sizeof(leftovers_specs[0])
 			},
 			.eth_flow = {
 				.type = IB_FLOW_SPEC_ETH,
 				.size = sizeof(struct ib_flow_spec_eth),
 				.mask = {.dst_mac = {0x1} },
 				.val = {.dst_mac = {} }
 			}
 		}
 	};

 	handler = create_flow_rule(dev, ft_prio,
 				   &leftovers_specs[LEFTOVERS_MC].flow_attr,
 				   dst);
 	if (!IS_ERR(handler) &&
 	    flow_attr->type == IB_FLOW_ATTR_ALL_DEFAULT) {
 		handler_ucast = create_flow_rule(dev, ft_prio,
 						 &leftovers_specs[LEFTOVERS_UC].flow_attr,
 						 dst);
 		if (IS_ERR(handler_ucast)) {
+			mlx5_del_flow_rule(handler->rule);
 			kfree(handler);
 			handler = handler_ucast;
 		} else {
 			list_add(&handler_ucast->list, &handler->list);
 		}
 	}

 	return handler;
 }



